begin;
create table public.apostolic_scout_missions(id uuid primary key default gen_random_uuid(),scout_city_id uuid not null references public.apostolic_cities(id)on delete cascade,target_city_id uuid not null references public.apostolic_cities(id)on delete cascade,status text not null default'scouting'check(status in('scouting','reported')),intel_level smallint not null check(intel_level between 1 and 3),discovery_chance smallint not null check(discovery_chance between 5 and 95),discovered boolean,started_at timestamptz not null default clock_timestamp(),finishes_at timestamptz not null,reported_at timestamptz,idempotency_key uuid not null,unique(scout_city_id,idempotency_key));
create unique index apostolic_scout_one_active_idx on public.apostolic_scout_missions(scout_city_id)where status='scouting';
create table public.apostolic_scout_reports(id uuid primary key default gen_random_uuid(),mission_id uuid not null unique references public.apostolic_scout_missions(id)on delete cascade,owner_id uuid not null references public.profiles(id)on delete cascade,target_city_name text not null,intel jsonb not null,discovered boolean not null,created_at timestamptz not null default clock_timestamp());
create table public.apostolic_counterintel_alerts(id bigint generated always as identity primary key,defender_id uuid not null references public.profiles(id)on delete cascade,source_city_id uuid references public.apostolic_cities(id)on delete set null,detail text not null,created_at timestamptz not null default clock_timestamp());
alter table public.apostolic_scout_missions enable row level security;alter table public.apostolic_scout_reports enable row level security;alter table public.apostolic_counterintel_alerts enable row level security;
create policy scout_missions_self on public.apostolic_scout_missions for select to authenticated using(exists(select 1 from public.apostolic_cities c where c.id=scout_city_id and c.owner_id=(select auth.uid())));create policy scout_reports_self on public.apostolic_scout_reports for select to authenticated using(owner_id=(select auth.uid()));create policy counterintel_self on public.apostolic_counterintel_alerts for select to authenticated using(defender_id=(select auth.uid()));
revoke all on public.apostolic_scout_missions,public.apostolic_scout_reports,public.apostolic_counterintel_alerts from anon,authenticated;grant select on public.apostolic_scout_missions,public.apostolic_scout_reports,public.apostolic_counterintel_alerts to authenticated;
create or replace function public.apostolic_get_spy_center()returns jsonb language sql stable security definer set search_path=''as $$with own as(select id,province_id from public.apostolic_cities where owner_id=(select auth.uid()))select jsonb_build_object('targets',(select coalesce(jsonb_agg(jsonb_build_object('id',c.id,'name',c.name,'level',c.level,'slot',c.slot_no)order by c.slot_no),'[]'::jsonb)from public.apostolic_cities c where c.province_id=(select province_id from own)and c.id<>(select id from own)),'mission',(select to_jsonb(x)from(select id,target_city_id,intel_level,discovery_chance,finishes_at,status from public.apostolic_scout_missions where scout_city_id=(select id from own)and status='scouting'limit 1)x),'reports',(select coalesce(jsonb_agg(to_jsonb(r)order by created_at desc),'[]'::jsonb)from(select target_city_name,intel,discovered,created_at from public.apostolic_scout_reports where owner_id=(select auth.uid())order by created_at desc limit 20)r),'alerts',(select coalesce(jsonb_agg(to_jsonb(a)order by created_at desc),'[]'::jsonb)from(select detail,created_at from public.apostolic_counterintel_alerts where defender_id=(select auth.uid())order by created_at desc limit 10)a))$$;
create or replace function public.apostolic_start_scout_mission(p_target_city_id uuid,p_intel_level integer,p_idempotency_key uuid)returns jsonb language plpgsql security definer set search_path=''as $$declare uid uuid:=(select auth.uid());cid uuid;pid uuid;target public.apostolic_cities%rowtype;academy integer;chance integer;duration integer;cost integer;oil bigint;begin if uid is null or p_idempotency_key is null or p_intel_level not between 1 and 3 then raise exception'invalid mission';end if;select id,province_id into cid,pid from public.apostolic_cities where owner_id=uid for update;select*into target from public.apostolic_cities where id=p_target_city_id and province_id=pid and id<>cid;if not found then raise exception'invalid target';end if;if exists(select 1 from public.apostolic_scout_missions where scout_city_id=cid and idempotency_key=p_idempotency_key)then return public.apostolic_get_spy_center();end if;if exists(select 1 from public.apostolic_scout_missions where scout_city_id=cid and status='scouting')then raise exception'scout already active';end if;select level into academy from public.apostolic_city_buildings where city_id=cid and building='academy';chance:=greatest(10,55+p_intel_level*10-academy*5-target.level*2);duration:=60+p_intel_level*60;cost:=20+p_intel_level*15;select amount into oil from public.apostolic_city_resources where city_id=cid and resource='oil'for update;if coalesce(oil,0)<cost then raise exception'insufficient oil';end if;update public.apostolic_city_resources set amount=amount-cost where city_id=cid and resource='oil';insert into public.apostolic_resource_ledger(city_id,resource,delta,balance_after,reason,idempotency_key)values(cid,'oil',-cost,oil-cost,'scout_mission',p_idempotency_key);insert into public.apostolic_scout_missions(scout_city_id,target_city_id,intel_level,discovery_chance,finishes_at,idempotency_key)values(cid,target.id,p_intel_level,chance,clock_timestamp()+make_interval(secs=>duration),p_idempotency_key);return public.apostolic_get_spy_center();end;$$;
create or replace function public.apostolic_finish_scout_mission()returns jsonb language plpgsql security definer set search_path=''as $$declare uid uuid:=(select auth.uid());cid uuid;m public.apostolic_scout_missions%rowtype;t public.apostolic_cities%rowtype;seen boolean;intel jsonb;begin select id into cid from public.apostolic_cities where owner_id=uid;select*into m from public.apostolic_scout_missions where scout_city_id=cid and status='scouting'for update;if not found then return public.apostolic_get_spy_center();end if;if m.finishes_at>clock_timestamp()then raise exception'scouting in progress';end if;select*into t from public.apostolic_cities where id=m.target_city_id;seen:=(floor(random()*100)+1)<=m.discovery_chance;intel:=jsonb_build_object('city_level',t.level,'wall_level',(select level from public.apostolic_city_buildings where city_id=t.id and building='wall'));if m.intel_level>=2 then intel:=intel||jsonb_build_object('defense_power',(select coalesce(sum(g.ready*u.defense),0)from public.apostolic_city_garrison g join public.apostolic_unit_catalog u on u.code=g.unit_code where g.city_id=t.id));end if;if m.intel_level>=3 then intel:=intel||jsonb_build_object('resources',(select jsonb_object_agg(resource,round(amount/100.0)*100)from public.apostolic_city_resources where city_id=t.id));end if;update public.apostolic_scout_missions set status='reported',discovered=seen,reported_at=clock_timestamp()where id=m.id;insert into public.apostolic_scout_reports(mission_id,owner_id,target_city_name,intel,discovered)values(m.id,uid,t.name,intel,seen);if seen then insert into public.apostolic_counterintel_alerts(defender_id,source_city_id,detail)values(t.owner_id,cid,'Batedores estrangeiros foram detectados perto da cidade.');end if;return public.apostolic_get_spy_center();end;$$;
revoke all on function public.apostolic_get_spy_center(),public.apostolic_start_scout_mission(uuid,integer,uuid),public.apostolic_finish_scout_mission()from public;grant execute on function public.apostolic_get_spy_center(),public.apostolic_start_scout_mission(uuid,integer,uuid),public.apostolic_finish_scout_mission()to authenticated;commit;
